import 'dart:async';import 'package:flutter_bloc/flutter_bloc.dart';import '../../domain/use_cases/watch_order_use_case.dart';import 'package:cloud_firestore/cloud_firestore.dart';
sealed class OrderTrackingState{const OrderTrackingState();}class OrderTrackingInitial extends OrderTrackingState{const OrderTrackingInitial();}class OrderTrackingLoading extends OrderTrackingState{const OrderTrackingLoading();}class OrderTrackingLoaded extends OrderTrackingState{const OrderTrackingLoaded(this.data);final Map<String,dynamic> data;}class OrderTrackingFailure extends OrderTrackingState{const OrderTrackingFailure(this.message);final String message;}
class OrderTrackingCubit extends Cubit<OrderTrackingState>{OrderTrackingCubit({required WatchOrderUseCase watchOrder}):_watchOrder=watchOrder,super(const OrderTrackingInitial());final WatchOrderUseCase _watchOrder;StreamSubscription<DocumentSnapshot<Map<String,dynamic>>>? _sub;void watch(String id){_sub?.cancel();emit(const OrderTrackingLoading());_sub=_watchOrder(id).listen((s){if(!s.exists){emit(const OrderTrackingFailure('Order not found'));return;}emit(OrderTrackingLoaded(s.data()??{}));},onError:(e)=>emit(OrderTrackingFailure(e.toString())));} @override Future<void> close()async{await _sub?.cancel();return super.close();}}
